import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.kOe0DhAP.js";const p=JSON.parse('{"title":"资产体系与余额设计","description":"以账户、余额和业务流水建立资金的解释链。","frontmatter":{"title":"资产体系与余额设计","description":"以账户、余额和业务流水建立资金的解释链。"},"headers":[],"relativePath":"05/0501/050001.md","filePath":"05/0501/050001.md"}'),n={name:"05/0501/050001.md"};function s(c,a,l,i,d,h){return t(),o("div",null,[...a[0]||(a[0]=[r('<div class="doc-eyebrow">资产与账务 / TGEX KNOWLEDGE BASE</div><h1 id="资产体系与余额设计" tabindex="-1">资产体系与余额设计 <a class="header-anchor" href="#资产体系与余额设计" aria-label="Permalink to &quot;资产体系与余额设计&quot;">​</a></h1><div class="doc-lead">以账户、余额和业务流水建立资金的解释链。</div><h2 id="accounts" tabindex="-1">账户分类 <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;账户分类 {#accounts}&quot;">​</a></h2><p>工程中可见现货、OTC、期权等业务账户相关实现。账户划分用于隔离不同业务的资金占用和结算规则，展示时应说明当前余额属于哪个账户。</p><h2 id="balances" tabindex="-1">可用与冻结 <a class="header-anchor" href="#balances" aria-label="Permalink to &quot;可用与冻结 {#balances}&quot;">​</a></h2><p>教学模型中，总额 = 可用余额 + 冻结余额。冻结表示资金仍属于用户，但已被某个订单或提现占用。冻结不是已经支付，解冻也不是新增收益。</p><p>合约还需要权益、保证金与未实现盈亏等口径，不能直接套用简单现货余额公式。</p><h2 id="journal" tabindex="-1">流水 <a class="header-anchor" href="#journal" aria-label="Permalink to &quot;流水 {#journal}&quot;">​</a></h2><p>流水应能关联业务编号、账户、币种、变动类型和变动金额。同一资金动作重试时，应识别既有处理结果，而不是创建第二笔无关记录。</p>',10)])])}const u=e(n,[["render",s]]);export{p as __pageData,u as default};
